<?php
namespace App\Collaboration;
use App\Models\{ResourceCollaborator,User};use Illuminate\Database\Eloquent\Model;
final class WebhookCollaborationAuthorizer implements CollaborationResourceAuthorizer{private function admin(User$u,Model$r):bool{return$u->isActive()&&$u->isPlatformAdmin()&&(int)$u->organization_id===(int)$r->getAttribute('organization_id');}private function permission(User $u,Model $r):?string{if(!$u->isActive()||(int)$u->organization_id!==(int)$r->getAttribute('organization_id'))return null;return ResourceCollaborator::where(['resource_type'=>'webhook','resource_id'=>$r->getKey(),'user_id'=>$u->id])->value('permission');}public function canView(User $u,Model $r):bool{return $this->admin($u,$r)||in_array($this->permission($u,$r),['view','edit'],true);}public function canEdit(User $u,Model $r):bool{return $this->admin($u,$r)||$this->permission($u,$r)==='edit';}public function canShare(User $u,Model $r):bool{return $this->canEdit($u,$r);}public function canComment(User $u,Model $r):bool{return $this->canView($u,$r);}public function canReview(User $u,Model $r):bool{return $this->canView($u,$r);}public function canAdminister(User $u,Model $r):bool{return $this->admin($u,$r);}}
